CREATE TABLE IF NOT EXISTS message_reviews (id INTEGER PRIMARY KEY, message_analysis_id INTEGER UNIQUE, email_analysis_id INTEGER UNIQUE, status VARCHAR(30) NOT NULL DEFAULT 'PENDING_REVIEW', assigned_reviewer VARCHAR(512), decision_reason TEXT, created_by VARCHAR(512) NOT NULL, updated_by VARCHAR(512) NOT NULL, created_at TIMESTAMP, updated_at TIMESTAMP, FOREIGN KEY(message_analysis_id) REFERENCES message_analysis_records(id), FOREIGN KEY(email_analysis_id) REFERENCES email_analyses(id));
CREATE INDEX IF NOT EXISTS ix_message_reviews_status ON message_reviews(status);
CREATE TABLE IF NOT EXISTS message_review_audits (id INTEGER PRIMARY KEY, review_id INTEGER NOT NULL, reviewer_id VARCHAR(512) NOT NULL, action VARCHAR(60) NOT NULL, previous_status VARCHAR(30), new_status VARCHAR(30), reason TEXT, note TEXT, created_at TIMESTAMP, FOREIGN KEY(review_id) REFERENCES message_reviews(id));
CREATE INDEX IF NOT EXISTS ix_message_review_audits_review_id ON message_review_audits(review_id);
CREATE TABLE IF NOT EXISTS message_review_feedback (id INTEGER PRIMARY KEY, review_id INTEGER NOT NULL, reviewer_id VARCHAR(512) NOT NULL, label VARCHAR(40) NOT NULL, certainty VARCHAR(30), evidence TEXT, approval_status VARCHAR(30) NOT NULL DEFAULT 'PENDING_VALIDATION', created_at TIMESTAMP, FOREIGN KEY(review_id) REFERENCES message_reviews(id));
CREATE INDEX IF NOT EXISTS ix_message_review_feedback_review_id ON message_review_feedback(review_id);
